export const SIGNED_HEADERS = [
  "from",
  "to",
  "cc",
  "bcc",
  "subject",
  "date",
  "message-id",
];

export interface Signature {
  selector: string;
  domain: string;
  headers: string[];
  bodyHash: string;
}

export function sign(raw: string, selector: string, domain: string): Signature {
  return { selector, domain, headers: [...SIGNED_HEADERS], bodyHash: bodyHash(raw) };
}

function bodyHash(raw: string): string {
  let value = 0;
  for (const char of raw) value = (value * 31 + char.codePointAt(0)!) % 2147483647;
  return value.toString(16);
}

