import { sign } from "./dkim.js";

export interface Message {
  id: string;
  recipients: string[];
  raw: string;
}

export type Outcome = "sent" | "deferred" | "dead";

export async function deliver(
  message: Message,
  handoff: (raw: string) => Promise<boolean>,
  attempt = 0,
): Promise<Outcome> {
  const signature = sign(message.raw, "relay2024", "example.com");
  const accepted = await handoff(`${signature.selector}:${message.raw}`);
  if (accepted) return "sent";
  return attempt >= 4 ? "dead" : "deferred";
}

