export interface Bounce {
  code: number;
  enhanced: string | null;
  recipient: string;
  text: string;
}

const LINE = /^(\d{3})[ -](?:(\d\.\d\.\d)\s+)?(.*)$/u;

export function parseBounce(line: string, recipient: string): Bounce | null {
  const match = LINE.exec(line.trim());
  if (!match) return null;
  return {
    code: Number(match[1]),
    enhanced: match[2] ?? null,
    recipient,
    text: match[3] ?? "",
  };
}

